    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    markers = []
    for color, cells in comps:
        pts = set(cells)
        for r, c in pts:
            for hd in (-1, 1):
                hl = 0
                while (r, c + hd * (hl + 1)) in pts:
                    hl += 1
                for vd in (-1, 1):
                    vl = 0
                    while (r + vd * (vl + 1), c) in pts:
                        vl += 1
                    if hl < 3 or vl < 3:
                        continue
                    arms = {(r, c)}
                    arms.update((r, c + hd * k) for k in range(1, hl + 1))
                    arms.update((r + vd * k, c) for k in range(1, vl + 1))
                    if arms == pts:
                        markers.append((hl + vl, color, cells, r, c, hd, vd))

    if not markers:
        return [row[:] for row in grid]

