    # The object to recolor is in the open quadrant of the L.
    candidates = []
    for color, cells in comps:
        if color == marker_color:
            continue
        eligible = [(r, c) for r, c in cells
                    if (r - cr) * vd <= 0 and (c - cc) * hd <= 0]
        if not eligible:
            continue
        dist = min(abs(r - mr) + abs(c - mc)
                   for r, c in eligible for mr, mc in marker_cells)
        candidates.append((dist, -len(cells), color, cells))

    if not candidates:
        return [row[:] for row in grid]

    _, _, _, target = min(candidates)
    out = [row[:] for row in grid]
